				FRotator WithZero = Rotator + FRotator::ZeroRotator;
				return Sum.Pitch == 11.0 && Sum.Yaw == 22.0 && Sum.Roll == 33.0 && WithZero.Pitch == 10.0 && Rotator.Pitch == 10.0;
